1	import { hashToken, verify as verifyToken, type Caller } from "./auth.js";
2	import { askFor, fits, framesForGesture, loadoutFor, profileOf, setupFor } from "./control.js";
3	import { askAllowed } from "./asking.js";
4	import { apiGatewayPoster, type Poster } from "./live.js";
5	import { dynamoLive, type LiveStore } from "./live.js";
6	import { dynamoStore, type Ask, type Store } from "./store.js";
7	import { dynamoRaces, type RaceStore } from "./races.js";
8	import { annotate } from "./xray.js";
9	import { randomBytes } from "node:crypto";
10	
11	/**
12	 * The socket's three moments.
13	 *
14	 * Connect: the token rides in the query string, because a browser's
15	 * WebSocket cannot set a header. It is checked the same way the HTTP API
16	 * checks a bearer, and a bad one is refused before the socket opens.
17	 * Message: the one thing a device says is which session it is watching;
18	 * it must be a member, and a session it may not see is ignored without
19	 * saying whether it exists. Disconnect: the rows go.
20	 *
21	 * A run shared by link admits a socket with no account: `?t=<token>&run=<id>`
22	 * opens a connection that watches that run and nothing else, and says
23	 * nothing it is told.
24	 *
25	 * Nothing else. Moves still travel over HTTP; the socket is a doorbell.
26	 */
27	
28	export interface WsEvent {
29	  requestContext: { routeKey: string; connectionId: string };
30	  queryStringParameters?: Record<string, string | undefined>;
31	  body?: string;
32	  isBase64Encoded?: boolean;
33	}
34	
35	export interface WsDeps {
36	  live: LiveStore;
37	  /** A way to post to connections; absent in a test that only checks routing. */
38	  poster?: Poster;
39	  store: Pick<Store, "getSession" | "streamKeyOwner" | "manifest" | "getSnapshot" | "addAsk" | "updateSession">;
40	  races: Pick<RaceStore, "getRace">;
41	  verify: (authorization: string | undefined) => Promise<Caller>;
42	  now?: () => string;
43	}
44	
45	interface WsResult {
46	  statusCode: number;
47	  body?: string;
48	}
49	
50	/**
51	 * A socket opened by something that drives a game rather than draws a
52	 * scoreboard.
53	 *
54	 * It arrives on the same addresses as every other watcher, with the same
55	 * keys, because what it is allowed to see is exactly what a watcher is
56	 * allowed to see. What it asks for in addition is to be told in
57	 * operations, and to say which player it is sitting in front of.
58	 */
59	function attachedOf(event: WsEvent, run: string): { control: true; seat?: string; run: string } | undefined {
60	  if (event.queryStringParameters?.["as"] !== "control") return undefined;
61	  const raw = (event.queryStringParameters?.["seat"] ?? "").trim().slice(0, 40);
62	  return { control: true, ...(raw ? { seat: raw } : {}), run };
63	}
64	
65	/**
66	 * A socket that presses rather than draws.
67	 *
68	 * It signs in as the account, the way the app's own devices do, because
69	 * what it may do is what the owner may do. It names no run at connect: it
70	 * is told which runs are being held, and picks. A link's token and a
71	 * stream key are refused here, which is why this is read only on the
72	 * signed-in branch below.
73	 */
74	function deckOf(event: WsEvent): { deck: true } | undefined {
75	  return event.queryStringParameters?.["as"] === "deck" ? { deck: true } : undefined;
76	}
77	
78	export async function route(event: WsEvent, deps: WsDeps): Promise<WsResult> {
79	  const { routeKey, connectionId } = event.requestContext;
80	  const now = deps.now ?? (() => new Date().toISOString());
81	  // The socket has no method, only which of its three moments this is.
82	  annotate({ method: "WS", route: routeKey });
83	
84	  if (routeKey === "$connect") {
85	    const t = event.queryStringParameters?.["t"];
86	    const run = event.queryStringParameters?.["run"];
87	    if (t && run) {
88	      const session = await deps.store.getSession(run);
89	      if (!session || session.meta.deletedAt || !session.meta.publicTokenHash || hashToken(t) !== session.meta.publicTokenHash)
90	        return { statusCode: 401, body: "not shared" };
91	      const who = `public:${run}`;
92	      const attached = attachedOf(event, run);
93	      await deps.live.connect(connectionId, who, now(), attached);
94	      await deps.live.watch(connectionId, run, who, now(), attached);
95	      return { statusCode: 200 };
96	    }
97	    /**
98	     * A scene's socket, opened on the account's watch key.
99	     *
100	     * The address in a browser source or a bot's client is set up once and
101	     * lives for months, so it cannot name a run: it names the account, and
102	     * this finds the run. Of the runs open to watchers, the one moved most
103	     * recently, which is the one being played.
104	     *
105	     * Which run it watches is settled when it connects. A socket open
106	     * across the start of a new run goes on watching the old one until it
107	     * is opened again; the bot hears `run-ended` on the old one, which is
108	     * the moment to reconnect.
109	     */
110	    const k = event.queryStringParameters?.["k"];
111	    if (k) {
112	      const owner = await deps.store.streamKeyOwner(hashToken(k));
113	      // A press key belongs in a bot's settings, never in a scene.
114	      if (!owner || owner.kind !== "watch") return { statusCode: 401, body: "not a key for watching" };
115	      const named = (event.queryStringParameters?.["run"] ?? "").trim();
116	      const { sessions } = await deps.store.manifest(owner.sub);
117	      const live = sessions
118	        .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt && (!named || p.id === named))
119	        .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
120	      let watching: string | null = null;
121	      for (const p of live)
122	        if ((await deps.store.getSession(p.id))?.meta.publicTokenHash) {
123	          watching = p.id;
124	          break;
125	        }
126	      if (!watching) return { statusCode: 401, body: "no run is open to watch" };
127	      const who = `stream:${owner.sub}`;
128	      const attached = attachedOf(event, watching);
129	      await deps.live.connect(connectionId, who, now(), attached);
130	      await deps.live.watch(connectionId, watching, who, now(), attached);
131	      return { statusCode: 200 };
132	    }
133	    const token = event.queryStringParameters?.["token"];
134	    let caller: Caller;
135	    try {
136	      caller = await deps.verify(token ? `Bearer ${token}` : undefined);
137	    } catch {
138	      return { statusCode: 401, body: "sign in first" };
139	    }
140	    const deck = deckOf(event);
141	    await deps.live.connect(connectionId, caller.sub, now(), deck);
142	    return { statusCode: 200 };
143	  }
144	
145	  /**
146	   * Who has a tool on the game right now, said to everyone watching.
147	   *
148	   * The whole set every time rather than a joining and a leaving. A table
149	   * that missed one message would otherwise show a tool that went home an
150	   * hour ago, or miss one that is about to be sent a curse, and there is
151	   * no cheap way to notice you missed it. A list is idempotent; a delta is
152	   * a thing to keep in step.
153	   */
154	  const tellWhoIsAttached = async (run: string): Promise<void> => {
155	    const poster = deps.poster;
156	    if (!poster) return;
157	    const watching = await deps.live.watchers(run);
158	    const tools = watching.filter((w) => w.control).map((w) => ({ ...(w.seat ? { seat: w.seat } : {}), ...(w.app ? { app: w.app } : {}) }));
159	    const line = JSON.stringify({ t: "gesture", id: run, kind: "tools", data: { tools, count: tools.length }, at: now() });
160	    for (const w of watching) {
161	      // A tool is told in operations, never in words about itself.
162	      if (w.control) continue;
163	      try {
164	        if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
165	      } catch (error) {
166	        console.error("live: could not say who is attached", error);
167	      }
168	    }
169	  };
170	
171	  if (routeKey === "$disconnect") {
172	    // Read before it goes: a tool leaving is news, and afterwards there is
173	    // nothing left to say which run it was on.
174	    const leaving = await deps.live.connection(connectionId);
175	    await deps.live.disconnect(connectionId);
176	    if (leaving?.control && leaving.run) await tellWhoIsAttached(leaving.run);
177	    return { statusCode: 200 };
178	  }
179	
180	  // $default: a message.
181	  const conn = await deps.live.connection(connectionId);
182	  if (!conn) return { statusCode: 401, body: "unknown connection" };
183	  let message: unknown;
184	  try {
185	    const raw = event.isBase64Encoded ? Buffer.from(event.body ?? "", "base64").toString("utf8") : (event.body ?? "");
186	    message = JSON.parse(raw);
187	  } catch {
188	    return { statusCode: 400, body: "JSON, please" };
189	  }
190	  if (!message || typeof message !== "object") return { statusCode: 400, body: "an object" };
191	  const m = message as Record<string, unknown>;
192	
193	  /**
194	   * A tool saying what it is and what it can do.
195	   *
196	   * The one message an attached tool sends, and the only one any of them
197	   * may: what comes back is the run's own terms, the settings it wants in
198	   * force before anything is rolled. Everything else it hears is sent
199	   * because the table moved, never because it asked.
200	   *
201	   * What the tool can do is not read here. A source that only ever sends
202	   * what a profile names cannot send an operation an old build lacks, and
203	   * a build that receives one refuses it by name, which is the answer in
204	   * both directions.
205	   */
206	  if (conn.control && m["t"] === "hello" && conn.run) {
207	    // What it calls itself is remembered, because a profile written for
208	    // one program must not drive another that happens to share an
209	    // operation name.
210	    const app = typeof m["app"] === "string" ? m["app"].trim().slice(0, 64) : "";
211	    await deps.live.watch(connectionId, conn.run, conn.sub, now(), {
212	      control: true,
213	      ...(conn.seat ? { seat: conn.seat } : {}),
214	      ...(app ? { app } : {}),
215	      run: conn.run,
216	    });
217	
218	    // The table hears that somebody's game is on the other end of this.
219	    // Said here rather than at connect, because until the hello arrives
220	    // there is no seat and no name to say, and a row with neither is not
221	    // worth drawing.
222	    await tellWhoIsAttached(conn.run);
223	
224	    const poster = deps.poster;
225	    if (!poster) return { statusCode: 200 };
226	    const snapshot = await deps.store.getSnapshot(conn.run);
227	    const profile = snapshot ? profileOf(snapshot.snapshot) : null;
228	    // Told rather than left silent: a tool sitting there doing nothing
229	    // is the most confusing thing this could do. Which is what it did
230	    // until now in the one case that matters most, the run it found
231	    // having no rules at all: an address names an account and the
232	    // server picks the run, so a tool can attach perfectly to a run
233	    // nobody is playing and report itself connected for ever.
234	    const session = await deps.store.getSession(conn.run);
235	    const which = session?.meta.packTitle ?? "a run";
236	    /**
237	     * Who has already had the parts of the terms that are given once.
238	     *
239	     * A seat, or the table where a tool named none. The terms go out on
240	     * every attach, because a tool that restarted is holding none of
241	     * them and a setting applied twice is the same setting. A gift is
242	     * not: a run whose terms hand over runes or an item handed them over
243	     * again on every reconnect, and by the third one it is a different
244	     * game. So the run remembers, and those parts are left out.
245	     */
246	    const whose = conn.seat || "the table";
247	    const given = session?.meta.termsGiven ?? [];
248	    const gotLoadout = session?.meta.loadoutGiven ?? [];
249	    /*
250	     * Two effects, not one. The pack's terms and the loadout chosen for
251	     * this run are one list in the profile and go out as two applies,
252	     * because the loadout has a button that re-sends it and a tool
253	     * re-applying an id takes the old one off first.
254	     */
255	    let terms: { frame: string; gave: boolean } | null = null;
256	    let loadout: { frame: string; gave: boolean } | null = null;
257	    const lines: string[] = [];
258	    if (!profile) {
259	      lines.push(
260	        JSON.stringify({
261	          t: "note",
262	          text: `Attached to ${which}, which has no rules for a tool. An address finds the most recently played run that is open to watchers; if that is not the one you are playing, open that one to watchers and connect again.`,
263	        }),
264	      );
265	    } else if (!fits(profile, app || undefined)) {
266	      lines.push(
267	        JSON.stringify({
268	          t: "note",
269	          text: `${which} is set up for ${profile.tool}, so nothing here will reach ${app || "a tool that did not say what it is"}.`,
270	        }),
271	      );
272	    } else {
273	      terms = setupFor(profile, given.includes(whose));
274	      loadout = loadoutFor(profile, gotLoadout.includes(whose));
275	      if (terms) lines.push(terms.frame);
276	      if (loadout) lines.push(loadout.frame);
277	    }
278	    for (const line of lines) {
279	      if ((await poster.post(connectionId, line)) === "gone") {
280	        await deps.live.disconnect(connectionId);
281	        return { statusCode: 200 };
282	      }
283	    }
284	    // Remembered only once it has actually gone out. A post that failed
285	    // is a tool that never got its terms, and marking it given would
286	    // leave the next attach short of them for the rest of the run.
287	    const patch: { termsGiven?: string[]; loadoutGiven?: string[] } = {};
288	    if (terms?.gave && !given.includes(whose)) patch.termsGiven = [...given, whose];
289	    if (loadout?.gave && !gotLoadout.includes(whose)) patch.loadoutGiven = [...gotLoadout, whose];
290	    if (patch.termsGiven || patch.loadoutGiven) await deps.store.updateSession(conn.run, now(), patch);
291	    return { statusCode: 200 };
292	  }
293	
294	  /**
295	   * A tool saying what happened in the game.
296	   *
297	   * The one thing that travels the other way. It is a mention rather than
298	   * a command: it becomes an ask, exactly as a viewer pressing a button
299	   * does, and the table still decides. Which is why this needs the host
300	   * to have switched asks on, and is refused as politely as anything else
301	   * when they have not.
302	   */
303	  if (conn.control && m["t"] === "event" && conn.run) {
304	    /**
305	     * Something the game said. Dropped for several good reasons, and it
306	     * used to be dropped in silence: every one of these answered 200, the
307	     * tool logged that it had said so, and a death counted nowhere. The
308	     * tool is told now, because "it went nowhere and here is why" is the
309	     * one thing it cannot work out from its end.
310	     */
311	    const drop = async (why: string): Promise<WsResult> => {
312	      const poster = deps.poster;
313	      if (poster) {
314	        try {
315	          await poster.post(connectionId, JSON.stringify({ t: "note", text: why }));
316	        } catch (error) {
317	          console.error("live: could not say why an event went nowhere", error);
318	        }
319	      }
320	      return { statusCode: 200 };
321	    };
322	    const meant = askFor(String(m["kind"] ?? ""));
323	    if (!meant) return drop(`This run has nothing it calls "${String(m["kind"] ?? "")}", so nothing was counted.`);
324	    const session = await deps.store.getSession(conn.run);
325	    if (!session || session.meta.deletedAt || session.meta.endedAt) return drop("That run has ended, so nothing was counted.");
326	    // Taking asks stays the host's word, per run, the same as it is for
327	    // chat. A tool cannot switch it on by being attached.
328	    if (!session.meta.askPolicy)
329	      return drop(
330	        "This run is not taking asks, so nothing was counted. Switch it on under Settings, Stream, Chat, and the game's word counts from then on.",
331	      );
332	    const who = conn.seat || "the game";
333	    const at = now();
334	    if (!askAllowed(conn.run, who, Date.parse(at)).ok) return drop("Too many, too quickly: this one was not counted.");
335	    const ask: Ask = { id: randomBytes(6).toString("hex"), kind: "move", move: meant.move, name: who, via: "the game", at };
336	    await deps.store.addAsk(conn.run, ask);
337	    const poster = deps.poster;
338	    // And when it did land, which of the two landings it was: taken, or
339	    // put in front of somebody. A tool that cannot tell those apart from
340	    // having been ignored is a tool nobody believes.
341	    if (poster) {
342	      const heard =
343	        session.meta.askPolicy === "auto" ? "Counted." : "Said. It is in the run's asks, waiting for whoever is at the table to take it.";
344	      try {
345	        await poster.post(connectionId, JSON.stringify({ t: "note", text: heard }));
346	      } catch (error) {
347	        console.error("live: could not say an event landed", error);
348	      }
349	    }
350	    if (poster) {
351	      const line = JSON.stringify({
352	        t: "gesture",
353	        id: conn.run,
354	        kind: "ask",
355	        data: { ask: ask.id, kind: ask.kind, move: ask.move, name: who, via: ask.via, policy: session.meta.askPolicy },
356	        at,
357	      });
358	      for (const w of await deps.live.watchers(conn.run)) {
359	        if (w.control) continue;
360	        try {
361	          if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
362	        } catch (error) {
363	          console.error("live: could not pass an ask on", error);
364	        }
365	      }
366	    }
367	
368	    return { statusCode: 200 };
369	  }
370	
371	  // A link's socket, and a scene's, watch the one run they were opened for
372	  // and take no requests.
373	  if (conn.sub.startsWith("public:") || conn.sub.startsWith("stream:")) return { statusCode: 200 };
374	  // A gesture: something happening at the table that is not a move, dice
375	  // in the air, a step opened, a card turned, passed straight on to
376	  // everyone watching the run and kept nowhere. Only a member sends one,
377	  // it is small, and its kind is a short word the app gives meaning to.
378	  if (m["t"] === "gesture" && typeof m["id"] === "string" && typeof m["kind"] === "string") {
379	    const id = m["id"];
380	    const kind = m["kind"];
381	    if (id.length > 200 || !/^[a-z][a-z0-9-]{0,31}$/.test(kind)) return { statusCode: 400, body: "a gesture has an id and a kind" };
382	    const data = m["data"] !== undefined && typeof m["data"] === "object" && m["data"] !== null ? m["data"] : {};
383	    if (JSON.stringify(data).length > 2000) return { statusCode: 400, body: "a gesture is small" };
384	    const session = await deps.store.getSession(id);
385	    const member = session && !session.meta.deletedAt ? session.members.find((x) => x.sub === conn.sub) : undefined;
386	    if (!member) return { statusCode: 200 };
387	    const line = JSON.stringify({ t: "gesture", id, kind, data, ...(member.name ? { from: member.name } : {}), at: now() });
388	    const poster = deps.poster;
389	
390	    /**
391	     * The loadout, handed out again on purpose.
392	     *
393	     * Every other gesture is passed on. This one means something to the
394	     * server, because the thing standing in the way of handing a loadout
395	     * out twice is a record the server keeps.
396	     *
397	     * `loadoutGiven` exists so that a tool which dropped and reconnected
398	     * is not given the runes again, and it has to go on doing that. But
399	     * a run whose host has picked a different loadout and pressed the
400	     * button is not a reconnect; it is somebody deciding that this table
401	     * is playing with different gear from now on. So the record is
402	     * cleared here and rebuilt from what actually goes out, and a
403	     * reconnect a second later is short of the gifts exactly as before.
404	     *
405	     * The loadout only. The pack's terms are a separate effect and are
406	     * not re-sent: the button is under a list of loadouts and says it
407	     * hands out the loadout, and sending the terms with it handed over
408	     * the pack's own gifts a second time as well.
409	     *
410	     * The owner only. Every member can send a gesture, and that is right
411	     * for dice in the air and a step opening; handing somebody a hundred
412	     * and twenty thousand runes is not something one player at the table
413	     * should be able to do to the others.
414	     *
415	     * Asked of the run rather than of the member row. Both say the same
416	     * thing today, and the run is the one that says it first: a member
417	     * row carries whatever was written into it when somebody joined.
418	     */
419	    if (kind === "setup") {
420	      if (session?.meta.ownerSub !== conn.sub) return { statusCode: 200 };
421	      if (!poster) return { statusCode: 200 };
422	      const watchers = await deps.live.watchers(id);
423	      const attached = watchers.filter((w) => w.control);
424	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
425	      const gave: string[] = [];
426	      await Promise.all(
427	        watchers.map(async (w) => {
428	          // The table is told in words that it happened; a tool is told
429	          // in operations, which is the same split as everywhere else.
430	          let out = w.connectionId === connectionId ? null : line;
431	          if (w.control) {
432	            if (!profile || !fits(profile, w.app)) return;
433	            // `false`, because being handed one is the whole point: the
434	            // record that would hold the gifts back has just been dropped.
435	            const loadout = loadoutFor(profile, false);
436	            if (!loadout) return;
437	            out = loadout.frame;
438	            if (loadout.gave) gave.push(w.seat || "the table");
439	          }
440	          if (!out) return;
441	          try {
442	            if ((await poster.post(w.connectionId, out)) === "gone") await deps.live.disconnect(w.connectionId);
443	          } catch (error) {
444	            console.error("live: could not hand out the setup", error);
445	          }
446	        }),
447	      );
448	      // Written after the fact, from what went out rather than from what
449	      // was meant to: a tool that was not reachable did not get its
450	      // loadout, and saying it did would leave it short on the next
451	      // attach. `termsGiven` is left alone, because the terms did not
452	      // move.
453	      await deps.store.updateSession(id, now(), { loadoutGiven: [...new Set(gave)] });
454	      return { statusCode: 200 };
455	    }
456	
457	    if (poster) {
458	      const watchers = (await deps.live.watchers(id)).filter((w) => w.connectionId !== connectionId);
459	      // A tool attached to somebody's game is told in operations rather
460	      // than in words, and the profile that decides which is read only
461	      // when one of them is listening.
462	      const attached = watchers.filter((w) => w.control);
463	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
464	      await Promise.all(
465	        watchers.map(async (w) => {
466	          const lines = !w.control ? [line] : profile && fits(profile, w.app) ? framesForGesture(profile, kind, data, w.seat) : [];
467	          for (const out of lines) {
468	            try {
469	              if ((await poster.post(w.connectionId, out)) === "gone") {
470	                await deps.live.disconnect(w.connectionId);
471	                return;
472	              }
473	            } catch (error) {
474	              console.error("live: could not pass a gesture on", error);
475	            }
476	          }
477	        }),
478	      );
479	    }
480	    return { statusCode: 200 };
481	  }
482	  if (m["t"] === "watch" && typeof m["id"] === "string" && m["id"].length > 0 && m["id"].length <= 200) {
483	    // A session or a race that is not theirs to see looks exactly like one
484	    // that is not there: the socket confirms nothing.
485	    const session = await deps.store.getSession(m["id"]);
486	    const inSession = Boolean(session && !session.meta.deletedAt && session.members.some((x) => x.sub === conn.sub));
487	    const race = inSession ? null : await deps.races.getRace(m["id"]);
488	    const inRace = Boolean(race && race.entries.some((e) => e.sub === conn.sub));
489	    if (!inSession && !inRace) return { statusCode: 200 };
490	    await deps.live.watch(connectionId, m["id"], conn.sub, now());
491	    return { statusCode: 200 };
492	  }
493	  return { statusCode: 400, body: "unknown message" };
494	}
495	
496	/* ---- the Lambda ---------------------------------------------------------- */
497	
498	let deps: WsDeps | undefined;
499	
500	export async function handler(event: WsEvent): Promise<WsResult> {
501	  if (!deps) {
502	    const clientId = process.env["WORKOS_CLIENT_ID"] ?? "";
503	    const cliClientId = process.env["WORKOS_CLI_CLIENT_ID"] ?? "";
504	    const table = process.env["TABLE_NAME"] ?? "";
505	    deps = {
506	      live: dynamoLive({ table }),
507	      store: dynamoStore({ table, bucket: process.env["BUCKET_NAME"] ?? "" }),
508	      races: dynamoRaces({ table }),
509	      verify: (authorization) => verifyToken(authorization, [clientId, cliClientId]),
510	      ...(process.env["WS_ENDPOINT"] ? { poster: apiGatewayPoster(process.env["WS_ENDPOINT"]) } : {}),
511	    };
512	  }
513	  try {
514	    return await route(event, deps);
515	  } catch (error) {
516	    console.error(error);
517	    return { statusCode: 500, body: "something went wrong on this side" };
518	  }
519	}
