/** What a member's own partition says about a session: enough to list it. */
export interface SessionPointer {
  id: string;
  role: Role;
  packId: string;
  packVersion: string;
  packTitle?: string;
  name?: string;
  ownerSub: string;
  updatedAt: string;
  seq: number;
  endedAt?: string;
  deletedAt?: string;
}

/** An invitation to a session, keyed by its token. */
export interface Invite {
  token: string;
  sessionId: string;
  email: string;
  role: Role;
  invitedBy: string;
  invitedByName?: string;
  createdAt: string;
  expiresAt: string;
  acceptedBy?: string;
  acceptedAt?: string;
}

/** Somebody the account has shared a session with, for the picker. */
export interface Person {
  sub: string;
  name?: string;
  email?: string;
  lastPlayedAt: string;
}

