    const mine = sessions
      .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt)
      .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0))
      .slice(0, 20);
